{"content": "import subprocess, sys
from pathlib import Path

# Also check Python version
print(f"Python: {sys.version}")

pkgs = ['requests', 'duckduckgo_search', 'beautifulsoup4', 'lxml']
for p in pkgs:
    try:
        mod = __import__(p.replace('_', '-').split('-')[0] if '-' in p else p)
        # Try to get version
        ver = getattr(mod, '__version__', '?')
        print(f"{p}: INSTALLED ({ver})")
    except ImportError:
        r = subprocess.run([sys.executable, '-m', 'pip', 'show', p], capture_output=True, text=True)
        if r.returncode == 0:
            ver = [l for l in r.stdout.split('\n') if l.startswith('Version:')]
            print(f"{p}: INSTALLED ({ver[0].split(':')[1].strip() if ver else '?'})")
        else:
            print(f"{p}: NOT INSTALLED")
